def current_rows(events):
    latest = {}
    for event in sorted(events, key=lambda e: (e['id'], e['event_time'], e['seq'])):
        latest[event['id']] = event

    result = []
    for id_ in sorted(latest):
        event = latest[id_]
        if event['op'] != 'D':
            result.append({'id': id_, 'value': event['value']})
    return result

from heapq import heappush, heappop

def stable_toposort(graph):
    dependents = {node: [] for node in graph}
    remaining = {}

    for node, deps in graph.items():
        seen = set()
        for dep in deps:
            try:
                present = dep in graph
            except TypeError:
                present = False
            if not present:
                raise ValueError("missing dependency: " + repr(dep))
            if dep not in seen:
                seen.add(dep)
                dependents[dep].append(node)
        remaining[node] = len(seen)

    index = {node: i for i, node in enumerate(graph)}
    ready = []
    for node in graph:
        if remaining[node] == 0:
            heappush(ready, (index[node], node))

    result = []
    while ready:
        _, node = heappop(ready)
        result.append(node)
        for dependent in dependents[node]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heappush(ready, (index[dependent], dependent))

    if len(result) != len(graph):
        raise ValueError("cycle detected")

    return result

def schema_drift(expected, actual):
    def flatten(node, prefix=""):
        paths = {}
        for key, value in node.items():
            path = f"{prefix}.{key}" if prefix else key
            if isinstance(value, dict):
                paths.update(flatten(value, path))
            else:
                paths[path] = value
        return paths

    exp = flatten(expected)
    act = flatten(actual)

    result = []
    for path in sorted(exp.keys() - act.keys()):
        result.append(path)
    for path in sorted(act.keys() - exp.keys()):
        result.append(path)
    for path in sorted(exp.keys() & act.keys()):
        if exp[path] != act[path]:
            result.append(path)

    return sorted(result)

def bounded_batches(items, max_rows):
    if max_rows <= 0:
        raise ValueError("max_rows must be positive")

    batches = []
    current_batch = []
    current_rows = 0

    for partition, row_count in items:
        if row_count > max_rows:
            if current_batch:
                batches.append(current_batch)
                current_batch = []
                current_rows = 0
            batches.append([(partition, row_count)])
            continue

        if current_rows + row_count > max_rows:
            batches.append(current_batch)
            current_batch = [(partition, row_count)]
            current_rows = row_count
        else:
            current_batch.append((partition, row_count))
            current_rows += row_count

    if current_batch:
        batches.append(current_batch)

    return batches

def merge_payload_ranges(items):
    by_payload = {}
    for start, end, payload in items:
        if start > end:
            raise ValueError("start must be <= end")
        by_payload.setdefault(payload, []).append((start, end))

    result = []
    for payload, ranges in by_payload.items():
        ranges.sort()
        merged = []
        for start, end in ranges:
            if merged and start <= merged[-1][1] + 1:
                if end > merged[-1][1]:
                    merged[-1][1] = end
            else:
                merged.append([start, end])

        for start, end in merged:
            result.append([start, end, payload])

    result.sort(key=lambda r: (r[0], r[1]))
    return result

def committable_windows(events, watermark):
    result = {}
    for event in events:
        if event["event_time"] <= watermark:
            continue
        window = event["window"]
        if window not in result:
            result[window] = []
        result[window].append(event["value"])
    return result
